// ReadSessionContent reads a session's metadata and prompts from the v2 /main ref,
// and the raw transcript (raw_transcript) from /full/* refs (current + archived generations).
// This is the v2 equivalent of GitStore.ReadSessionContent — it reads the raw agent
// transcript, not the compact transcript.jsonl. Used by resume and RestoreLogsOnly.
// Returns ErrNoTranscript if the session exists but no raw transcript is available.
// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
func (s *V2GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
	sessionTree, err := s.sessionTreeFromMain(ctx, checkpointID, sessionIndex)
	if err != nil {
		return nil, err
	}

	result := &SessionContent{}
	sessionFT := s.wrapWithFetcher(ctx, sessionTree)

	if metadataFile, fileErr := sessionFT.File(paths.MetadataFileName); fileErr == nil {
		if content, contentErr := metadataFile.Contents(); contentErr == nil {
			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
				return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
			}
		}
	}

	if file, fileErr := sessionFT.File(paths.PromptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Prompts = content
		}
	}

	transcript, transcriptErr := s.readTranscriptFromFullRefs(ctx, checkpointID, sessionIndex, result.Metadata.Agent)
	if transcriptErr != nil {
		return nil, fmt.Errorf("failed to read transcript from /full/* refs: %w", transcriptErr)
	}
	if len(transcript) == 0 {
		return nil, ErrNoTranscript
	}
	result.Transcript = transcript

	return result, nil
}

func (s *V2GitStore) sessionTreeFromMain(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*object.Tree, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	refName := plumbing.ReferenceName(paths.V2MainRefName)
	_, rootTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	cpTree, err := rootTree.Tree(checkpointID.Path())
	if err != nil {
		return nil, ErrCheckpointNotFound
	}

	sessionDir := strconv.Itoa(sessionIndex)
	sessionTree, err := cpTree.Tree(sessionDir)
	if err != nil {
		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
	}

	return sessionTree, nil
}

// readTranscriptFromFullRefs reads the raw transcript for a checkpoint session
// by searching /full/current first, then archived generations in reverse order.
// If not found locally, attempts to discover and fetch remote /full/* refs.
func (s *V2GitStore) readTranscriptFromFullRefs(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, agentType types.AgentType) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err //nolint:wrapcheck // Propagating context cancellation
	}

	sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)

	// Search locally first
	transcript, err := s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
	if err == nil && len(transcript) > 0 {
		return transcript, nil
	}

	archived, err := s.ListArchivedGenerations()
	if err != nil {
		return nil, err
	}
	for i := len(archived) - 1; i >= 0; i-- {
		refName := plumbing.ReferenceName(paths.V2FullRefPrefix + archived[i])
		transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
		if err == nil && len(transcript) > 0 {
			return transcript, nil
		}
	}

	// Not found locally — try fetching remote /full/* refs
	if fetchErr := s.fetchRemoteFullRefs(ctx); fetchErr != nil {
		logging.Debug(ctx, "failed to fetch remote /full/* refs",
			slog.String("error", fetchErr.Error()),
		)
		return nil, nil
	}

	// Search newly fetched refs only
	newArchived, err := s.ListArchivedGenerations()
	if err != nil {
		return nil, nil //nolint:nilerr // Best-effort: fetch-on-demand failure shouldn't block resume
	}
	existingSet := make(map[string]bool, len(archived))
	for _, a := range archived {
		existingSet[a] = true
	}
	for i := len(newArchived) - 1; i >= 0; i-- {
		if existingSet[newArchived[i]] {
			continue
		}
		refName := plumbing.ReferenceName(paths.V2FullRefPrefix + newArchived[i])
		transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
		if err == nil && len(transcript) > 0 {
			return transcript, nil
		}
	}

	// Also retry /full/current in case it was updated by the fetch
	transcript, err = s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
	if err == nil && len(transcript) > 0 {
		return transcript, nil
	}

	return nil, nil
}

// fetchRemoteFullRefs discovers and fetches /full/* refs from the effective
// checkpoint fetch target that aren't local.
func (s *V2GitStore) fetchRemoteFullRefs(ctx context.Context) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	repoRoot, _, err := s.gs.repoDirs(ctx)
	if err != nil {
		return err
	}

	fetchTarget := v2FullRefsFetchTarget(ctx, repoRoot)
	output, err := remote.LsRemoteInDir(ctx, repoRoot, fetchTarget, paths.V2FullRefPrefix+"*")
	if err != nil {
		return fmt.Errorf("ls-remote failed: %w", err)
	}

	var refSpecs []string
	for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
		if line == "" {
			continue
		}
		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}
		remoteRefName := parts[1]

		// Skip refs that already exist locally
		if _, refErr := s.repo.Reference(plumbing.ReferenceName(remoteRefName), true); refErr == nil {
			continue
		}

		refSpecs = append(refSpecs, fmt.Sprintf("+%s:%s", remoteRefName, remoteRefName))
	}

	if len(refSpecs) == 0 {
		return nil
	}

	if fetchOutput, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
		Remote:   fetchTarget,
		RefSpecs: refSpecs,
		NoTags:   true,
		NoFilter: true,
		Dir:      repoRoot,
	}); fetchErr != nil {
		return fmt.Errorf("fetch failed: %s: %w", fetchOutput, fetchErr)
	}

	return nil
}

func v2FullRefsFetchTarget(ctx context.Context, repoRoot string) string {
	target, err := remote.FetchURL(ctx, remote.FetchURLOptions{WorktreeRoot: repoRoot})
	if err == nil && target != "" {
		return target
	}
	return "origin"
}

// readTranscriptFromRef reads the raw transcript from a specific /full/* ref.
// Follows the same chunking convention as readTranscriptFromTree in committed.go:
// chunk 0 is the base file (raw_transcript), chunks 1+ are raw_transcript.001, .002, etc.
// When chunk files exist, all chunks (including chunk 0) are reassembled using
// agent-aware reassembly via agent.ReassembleTranscript.
func (s *V2GitStore) readTranscriptFromRef(refName plumbing.ReferenceName, sessionPath string, agentType types.AgentType) ([]byte, error) {
	_, rootTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return nil, err
	}

	rootTree, err := s.repo.TreeObject(rootTreeHash)
	if err != nil {
		return nil, fmt.Errorf("failed to read tree: %w", err)
	}

	sessionTree, err := rootTree.Tree(sessionPath)
	if err != nil {
		return nil, fmt.Errorf("session path %s not found: %w", sessionPath, err)
	}

	return readTranscriptFromObjectTree(sessionTree, agentType)
}

// readTranscriptFromObjectTree reads and reassembles a transcript from a git tree object.
// Handles both chunked and non-chunked transcripts. Uses agent-aware reassembly
// when agentType is known, falling back to JSONL reassembly otherwise.
func readTranscriptFromObjectTree(tree *object.Tree, agentType types.AgentType) ([]byte, error) {
	var chunkFiles []string
	var hasBaseFile bool

	for _, entry := range tree.Entries {
		if entry.Name == paths.V2RawTranscriptFileName {
			hasBaseFile = true
		}
		if strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+".") {
			idx := agent.ParseChunkIndex(entry.Name, paths.V2RawTranscriptFileName)
			if idx > 0 {
				chunkFiles = append(chunkFiles, entry.Name)
			}
		}
	}

	// If chunk files exist, reassemble all chunks (base file is chunk 0)
	if len(chunkFiles) > 0 {
		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.V2RawTranscriptFileName)
		if hasBaseFile {
			chunkFiles = append([]string{paths.V2RawTranscriptFileName}, chunkFiles...)
		}

		var chunks [][]byte
		for _, chunkFile := range chunkFiles {
			file, fileErr := tree.File(chunkFile)
			if fileErr != nil {
				continue
			}
			content, contentErr := file.Contents()
			if contentErr != nil {
				continue
			}
			chunks = append(chunks, []byte(content))
		}

		if len(chunks) > 0 {
			result, reassembleErr := agent.ReassembleTranscript(chunks, agentType)
			if reassembleErr != nil {
				return nil, fmt.Errorf("failed to reassemble transcript: %w", reassembleErr)
			}
			return result, nil
		}
	}

	// No chunk files — read base file directly (non-chunked transcript)
	if hasBaseFile {
		file, err := tree.File(paths.V2RawTranscriptFileName)
		if err == nil {
			content, contentErr := file.Contents()
			if contentErr == nil {
				return []byte(content), nil
			}
		}
	}

	return nil, nil
}

// ReadSessionContentByID finds the session with the given sessionID in a checkpoint
// and returns its content. Mirrors GitStore.ReadSessionContentByID for v2 refs.
// Returns ErrCheckpointNotFound if the checkpoint doesn't exist; returns a
// non-wrapped error (containing the session ID and checkpoint ID for context)
// if no session in the checkpoint matches sessionID.
func (s *V2GitStore) ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error) {
	summary, err := s.ReadCommitted(ctx, checkpointID)
	if err != nil {
		return nil, err
	}
	if summary == nil {
		return nil, ErrCheckpointNotFound
	}

	for i := range summary.Sessions {
		content, readErr := s.ReadSessionContent(ctx, checkpointID, i)
		if readErr != nil {
			continue
		}
		if content != nil && content.Metadata.SessionID == sessionID {
			return content, nil
		}
	}

	return nil, fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID)
}

// GetSessionLog reads the latest session's raw transcript and session ID from v2 refs.
// Convenience wrapper matching the GitStore.GetSessionLog signature.
func (s *V2GitStore) GetSessionLog(ctx context.Context, cpID id.CheckpointID) ([]byte, string, error) {
	summary, err := s.ReadCommitted(ctx, cpID)
	if err != nil {
		return nil, "", err
	}
	if summary == nil {
		return nil, "", ErrCheckpointNotFound
	}
	if len(summary.Sessions) == 0 {
		return nil, "", ErrCheckpointNotFound
	}

	latestIndex := len(summary.Sessions) - 1
	content, err := s.ReadSessionContent(ctx, cpID, latestIndex)
	if err != nil {
		return nil, "", err
	}
	return content.Transcript, content.Metadata.SessionID, nil
}
func (s *V2GitStore) v2MainTree() (*object.Tree, error) {
	ref, err := s.repo.Reference(plumbing.ReferenceName(paths.V2MainRefName), true)
	if err != nil {
		return nil, fmt.Errorf("failed to read v2 main ref: %w", err)
	}
	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to read v2 main commit: %w", err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to read v2 main tree: %w", err)
	}
	return tree, nil
}

func (s *V2GitStore) checkpointTimestampRangeFromMain(mainTree *object.Tree, cpID id.CheckpointID) (GenerationMetadata, bool) {
	cpTree, err := mainTree.Tree(cpID.Path())
	if err != nil {
		return GenerationMetadata{}, false
	}

	var gen GenerationMetadata
	found := false
	for _, entry := range cpTree.Entries {
		if entry.Mode != filemode.Dir {
			continue
		}
		if _, err := strconv.Atoi(entry.Name); err != nil {
			continue
		}
		sessionTree, err := s.repo.TreeObject(entry.Hash)
		if err != nil {
			continue
		}
		metadataFile, err := sessionTree.File(paths.MetadataFileName)
		if err != nil {
			continue
		}
		metadataContent, err := metadataFile.Contents()
		if err != nil {
			continue
		}
		var metadata CommittedMetadata
		if err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil || metadata.CreatedAt.IsZero() {
			continue
		}
		MergeGenerationTime(&gen, &found, metadata.CreatedAt.UTC())
	}
	return gen, found
}

func checkpointTimestampRangeFromFullTree(cpTree *object.Tree) (GenerationMetadata, bool) {
	var gen GenerationMetadata
	found := false
	for _, entry := range cpTree.Entries {
		if entry.Mode != filemode.Dir {
			continue
		}
		if _, err := strconv.Atoi(entry.Name); err != nil {
			continue
		}
		sessionTree, err := cpTree.Tree(entry.Name)
		if err != nil {
			continue
		}
		transcript, err := readTranscriptFromObjectTree(sessionTree, "")
		if err != nil || len(transcript) == 0 {
			continue
		}
		if transcriptGen, ok := timestampRangeFromTranscript(transcript); ok {
			mergeGenerationRange(&gen, &found, transcriptGen)
		}
	}
	return gen, found
}

// AggregateTranscriptTimestamps derives a generation timestamp envelope from
// transcripts already in memory, using the same first/last-event semantics
// as ComputeGenerationTimestampsFromTrees but skipping the blob reads.
func AggregateTranscriptTimestamps(transcripts [][]byte) (GenerationMetadata, bool) {
	var gen GenerationMetadata
	found := false
	for _, transcript := range transcripts {
		if len(transcript) == 0 {
			continue
		}
		if r, ok := timestampRangeFromTranscript(transcript); ok {
			mergeGenerationRange(&gen, &found, r)
		}
	}
	return gen, found
}

func timestampRangeFromTranscript(transcript []byte) (GenerationMetadata, bool) {
	reader := bufio.NewReader(bytes.NewReader(transcript))
	var gen GenerationMetadata
	found := false

	for {
		line, err := reader.ReadBytes('\n')
		if trimmed := bytes.TrimSpace(line); len(trimmed) > 0 {
			var event struct {
				Timestamp string `json:"timestamp"`
			}
			if jsonErr := json.Unmarshal(trimmed, &event); jsonErr == nil && event.Timestamp != "" {
				if ts, parseErr := time.Parse(time.RFC3339Nano, event.Timestamp); parseErr == nil {
					MergeGenerationTime(&gen, &found, ts.UTC())
				}
			}
		}
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			break
		}
	}

	return gen, found
}

func mergeGenerationRange(dst *GenerationMetadata, found *bool, src GenerationMetadata) {
	MergeGenerationTime(dst, found, src.OldestCheckpointAt)
	MergeGenerationTime(dst, found, src.NewestCheckpointAt)
}

// MergeGenerationTime expands the generation timestamp envelope to include ts.
// The found flag is set the first time a non-zero timestamp is observed.
func MergeGenerationTime(gen *GenerationMetadata, found *bool, ts time.Time) {
	if ts.IsZero() {
		return
	}
	ts = ts.UTC()
	if !*found {
		gen.OldestCheckpointAt = ts
		gen.NewestCheckpointAt = ts
		*found = true
		return
	}
	if ts.Before(gen.OldestCheckpointAt) {
		gen.OldestCheckpointAt = ts
	}
	if ts.After(gen.NewestCheckpointAt) {
		gen.NewestCheckpointAt = ts
	}
}

// generationRefWidth is the zero-padded width of archived generation ref names.
const generationRefWidth = 13

// ArchivedGenerationRefName returns the full ref name for an archived generation number.
func ArchivedGenerationRefName(number int) plumbing.ReferenceName {
	return plumbing.ReferenceName(fmt.Sprintf("%s%0*d", paths.V2FullRefPrefix, generationRefWidth, number))
}

// GenerationRefPattern matches exactly 13 digits (the archived generation ref suffix format).
var GenerationRefPattern = regexp.MustCompile(`^\d{13}$`)

// listArchivedGenerations returns the names of all archived generation refs
// (everything under V2FullRefPrefix matching the expected numeric format), sorted ascending.
func (s *V2GitStore) ListArchivedGenerations() ([]string, error) {
	refs, err := s.repo.References()
	if err != nil {
		return nil, fmt.Errorf("failed to list references: %w", err)
	}

	var archived []string
	err = refs.ForEach(func(ref *plumbing.Reference) error {
		name := ref.Name().String()
		if !strings.HasPrefix(name, paths.V2FullRefPrefix) {
			return nil
		}
		suffix := strings.TrimPrefix(name, paths.V2FullRefPrefix)
		if suffix == "current" || !GenerationRefPattern.MatchString(suffix) {
			return nil
		}
		archived = append(archived, suffix)
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to iterate references: %w", err)
	}

	sort.Strings(archived)
	return archived, nil
}

// NextGenerationNumber returns the next sequential generation number for archiving.
// Scans existing archived refs and returns max+1. Returns 1 if no archives exist.
func (s *V2GitStore) NextGenerationNumber() (int, error) {
	archived, err := s.ListArchivedGenerations()
	if err != nil {
		return 0, err
	}

	var maxNum int64
	for _, name := range archived {
		n, parseErr := strconv.ParseInt(name, 10, 64)
		if parseErr != nil {
			continue // skip unparseable entries
		}
		if n > maxNum {
			maxNum = n
		}
	}
	return int(maxNum) + 1, nil
}

// RotateCurrentGenerationIfNeeded archives /full/current when it has reached
// maxCheckpoints. It returns the archived ref name when this call completes
// a rotation.
func (s *V2GitStore) RotateCurrentGenerationIfNeeded(ctx context.Context, maxCheckpoints int) (plumbing.ReferenceName, bool, error) {
	if maxCheckpoints <= 0 {
		maxCheckpoints = s.maxCheckpoints()
	}

	// This is a 2-phase operation:
	//
	//  1. Archive: determine the next generation number, create a new ref pointing
	//     to the current /full/current commit.
	//  2. Reset: create a fresh orphan commit with an empty tree, point
	//     /full/current at it.
	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)

	// Guard against concurrent rotation: re-read /full/current and check if
	// it's still above the threshold. If not, another instance already rotated.
	_, currentTreeHash, err := s.GetRefState(refName)
	if err != nil {
		return "", false, fmt.Errorf("rotation: failed to read /full/current: %w", err)
	}
	checkpointCount, err := s.CountCheckpointsInTree(ctx, currentTreeHash)
	if err != nil {
		return "", false, fmt.Errorf("rotation: failed to count checkpoints: %w", err)
	}
	if checkpointCount < maxCheckpoints {
		return "", false, nil
	}

	currentRef, err := s.repo.Reference(refName, true)
	if err != nil {
		return "", false, fmt.Errorf("rotation: failed to read /full/current ref: %w", err)
	}

	archiveNumber, err := s.NextGenerationNumber()
	if err != nil {
		return "", false, fmt.Errorf("rotation: failed to determine next generation number: %w", err)
	}

	// Phase 1: Prepare archive and reset commits without changing refs yet.
	// If the archive ref already exists, another instance already rotated — skip.
	archiveRefName := ArchivedGenerationRefName(archiveNumber)
	if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
		logging.Info(ctx, "rotation: archive ref already exists, skipping",
			slog.String("archive_ref", string(archiveRefName)),
		)
		return archiveRefName, false, nil
	}

	// Write generation.json to the current tree before archiving.
	gen := s.computeGenerationTimestamps(ctx, currentTreeHash)
	archiveTreeHash, err := s.AddGenerationJSONToTree(currentTreeHash, gen)
	if err != nil {
		return "", false, fmt.Errorf("rotation: failed to add generation.json: %w", err)
	}

	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
	archiveCommitHash, err := CreateCommit(ctx, s.repo, archiveTreeHash, currentRef.Hash(), "Archive generation", authorName, authorEmail)
	if err != nil {
		return "", false, fmt.Errorf("rotation: failed to create archive commit: %w", err)
	}

	// Create fresh orphan /full/current (empty tree, no generation.json).
	emptyTreeHash, err := BuildTreeFromEntries(ctx, s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return "", false, fmt.Errorf("rotation: failed to build empty tree: %w", err)
	}

	orphanCommitHash, err := CreateCommit(ctx, s.repo, emptyTreeHash, plumbing.ZeroHash, "Start generation", authorName, authorEmail)
	if err != nil {
		return "", false, fmt.Errorf("rotation: failed to create orphan commit: %w", err)
	}

	// Verify /full/current hasn't been advanced by another writer since we read it.
	// If it changed, abort before recording a publication marker.
	postArchiveRef, err := s.repo.Reference(refName, true)
	if err != nil {
		return "", false, fmt.Errorf("rotation: failed to re-read /full/current: %w", err)
	}
	if postArchiveRef.Hash() != currentRef.Hash() {
		logging.Info(ctx, "rotation: /full/current changed during rotation, aborting reset")
		return archiveRefName, false, nil
	}

	publication := PendingV2FullGenerationPublication{
		ArchiveRefName:           archiveRefName.String(),
		ArchiveCommitHash:        archiveCommitHash.String(),
		PreviousFullCurrentHash:  currentRef.Hash().String(),
		ResetFullCurrentRootHash: orphanCommitHash.String(),
		QueuedAt:                 time.Now().UTC(),
	}

	// The commit objects above are not reachable from the v2 refs yet. Record
	// the pending publication before moving refs. Pre-push drops stale reset
	// handoffs until the newest queued reset root is in local /full/current
	// history, then publishes the queued archive refs together.
	if err := s.AppendPendingFullGenerationPublication(ctx, publication); err != nil {
		return "", false, fmt.Errorf("rotation: failed to record pending full rotation: %w", err)
	}
	keepPendingPublication := false
	defer func() {
		if keepPendingPublication {
			return
		}
		if removeErr := s.RemovePendingFullGenerationPublications(ctx, []PendingV2FullGenerationPublication{publication}); removeErr != nil {
			logging.Warn(ctx, "rotation: failed to remove pending full rotation after failed rotation",
				slog.String("error", removeErr.Error()),
				slog.String("archive_ref", string(archiveRefName)),
				slog.String("previous_full_current_hash", currentRef.Hash().String()),
				slog.String("archive_commit_hash", archiveCommitHash.String()),
				slog.String("reset_full_current_root_hash", orphanCommitHash.String()),
			)
		}
	}()

	// Phase 2: publish local refs after the pending publication marker exists.
	if _, refErr := s.repo.Reference(archiveRefName, true); refErr == nil {
		logging.Info(ctx, "rotation: archive ref already exists, skipping",
			slog.String("archive_ref", string(archiveRefName)),
		)
		return archiveRefName, false, nil
	}
	archiveRef := plumbing.NewHashReference(archiveRefName, archiveCommitHash)
	if err := s.repo.Storer.SetReference(archiveRef); err != nil {
		return "", false, fmt.Errorf("rotation: failed to update archived ref %s: %w", archiveRefName, err)
	}

	reset, err := s.resetFullCurrentRefIfUnchanged(ctx, refName, postArchiveRef, orphanCommitHash)
	if err != nil {
		return "", false, err
	}
	if !reset {
		return archiveRefName, false, nil
	}

	keepPendingPublication = true
	logging.Info(ctx, "generation rotation complete",
		slog.Int("archived_generation", archiveNumber),
		slog.String("archive_ref", string(archiveRefName)),
	)

	return archiveRefName, true, nil
}

func (s *V2GitStore) resetFullCurrentRefIfUnchanged(ctx context.Context, refName plumbing.ReferenceName, expectedRef *plumbing.Reference, newHash plumbing.Hash) (bool, error) {
	newRef := plumbing.NewHashReference(refName, newHash)
	if err := s.repo.Storer.CheckAndSetReference(newRef, expectedRef); err != nil {
		if errors.Is(err, storage.ErrReferenceHasChanged) {
			logging.Info(ctx, "rotation: /full/current changed before reset, leaving current ref intact")
