+func discoverCheckpointHistory(ctx context.Context, repo *git.Repository, opts discoveryOptions) ([]discoveredCheckpoint, error) {
+	excluded, err := excludedCommits(ctx, repo, opts.since)
+	if err != nil {
+		return nil, err
+	}
