+		hash := ref.Hash()
+		if seenHashes[hash] {
+			return nil
+		}
+		seenHashes[hash] = true
+		tips = append(tips, historyTip{name: ref.Name().String(), hash: hash})
+		return nil
+	})
+	if err != nil {
